# MEXC %2 DEĞİŞİM ALARM SİSTEMİ
# ==========================================

_degisim_alarm_onceki = {}   # {sym: son_fiyat} — önceki kontrol fiyatı
_degisim_alarm_kilit  = threading.Lock()

def _degisim_alarm_kontrol():
    """MEXC Futures tüm pariteler — %2+ değişimde TOPIC_YUKSELENLER'e görsel + bildirim gönder."""
    global _degisim_alarm_onceki
    try:
        tickers = _tarayici_veri_cek()
        if not tickers:
            return

        if TR_TZ:
            zaman_str = datetime.now(tz=TR_TZ).strftime("%H:%M")
        else:
            zaman_str = datetime.utcnow().strftime("%H:%M UTC")

        with _degisim_alarm_kilit:
            for t in tickers:
                try:
                    sym = t.get("symbol", "")
                    if not sym.endswith("_USDT"):
                        continue
                    fiyat = float(t.get("lastPrice", 0))
                    if fiyat <= 0:
                        continue
                    kisa = sym.replace("_USDT", "")

                    onceki = _degisim_alarm_onceki.get(kisa)
                    _degisim_alarm_onceki[kisa] = fiyat

                    if onceki is None or onceki <= 0:
                        continue

                    degisim_pct = (fiyat - onceki) / onceki * 100

                    if abs(degisim_pct) < 2.0:
                        continue

                    yukari = degisim_pct >= 2.0
                    baslik_ikon  = "🟢" if yukari else "🔴"
                    baslik_metin = "YÜKSELİŞ ALARMI  📈" if yukari else "DÜŞÜŞ ALARMI 📉"
                    degis_ok     = "🟩" if yukari else "🟥"

                    if fiyat >= 1000:   fiyat_str = f"{fiyat:,.1f}"
                    elif fiyat >= 1:    fiyat_str = f"{fiyat:.4f}"
                    else:               fiyat_str = f"{fiyat:.6f}"

                    if yukari:
                        detail = "Hacim artışıyla birlikte breakout olabilir — long olta seviyelerini takip et."
                    else:
                        detail = "Stop tetikleniyor olabilir — short olta seviyelerini takip et."

                    cizgi = "―" * 20
                    mesaj = (
                        f"{cizgi}\n"
                        f"<b>{baslik_metin}</b> — {zaman_str}\n\n"
                        f"⚡ <b>{kisa}/USDT</b>\n"
                        f"📍 Fiyat: <b>{fiyat_str}</b> USDT\n"
                        f"{degis_ok} Değişim: <b>{degisim_pct:+.2f}%</b> (5dk)\n\n"
                        f"💬 {detail}\n"
                        f"{cizgi}"
                    )
                    _telegram_topic_mesaj_gonder(TOPIC_YUKSELENLER, mesaj)
                    print(f"[ALARM] {kisa} {degisim_pct:+.2f}% → metin gonderildi.")
                    time.sleep(2)  # flood önleme

                except Exception as e:
                    print(f"[ALARM] {sym} hata: {e}")

    except Exception as e:
        print(f"[ALARM] Genel hata: {e}")


def _degisim_alarm_zamanlayici():
    """Her 5 dakikada bir MEXC paritelerini tara, %2+ değişim varsa TOPIC_YUKSELENLER'e bildir."""
    print("[ALARM] %2 Degisim alarm zamanlayicisi basladi. Her 5 dakikada kontrol edilecek.")
    time.sleep(30)  # ilk tur için referans fiyatları doldur
    _degisim_alarm_kontrol()  # referans fiyatlarını yükle (bildirim göndermez, onceki=None)
    while True:
        try:
            time.sleep(300)  # 5 dakika
            _degisim_alarm_kontrol()
        except Exception as e:
            print(f"[ALARM] Zamanlayici hata: {e}")
            time.sleep(60)

def _tarayici_zamanlayici():
    """Her saat başında tarayıcı çalıştır."""
    import datetime as dt_mod

    print("[TARAYICI] Zamanlayici basladi.")
    while True:
        try:
            if TR_TZ:
                simdi = datetime.now(tz=TR_TZ)
            else:
                simdi = datetime.utcnow()

            # Bir sonraki saat başını hesapla
            sonraki = simdi.replace(minute=0, second=0, microsecond=0) + dt_mod.timedelta(hours=1)
            bekle = (sonraki - simdi).total_seconds()
            print(f"[TARAYICI] Sonraki rapor: {sonraki.strftime('%H:%M')} ({int(bekle//60)} dk sonra)")
            time.sleep(bekle)
            _tarayici_gonder()
            time.sleep(5)  # double-fire önleme
        except Exception as e:
            print(f"[TARAYICI] Zamanlayici hata: {e}")
            time.sleep(60)


